## ✅ Актуализированная версия `withAggregateRoot` с типами и корректной работой декораторов

```ts
import { AggregateRoot } from './aggregate-root';
import { Logger } from '@nestjs/common';

type Constructor<T = {}> = new (...args: any[]) => T;

export function withAggregateRoot<TBase extends Constructor>(
  Base: TBase
) {
  abstract class WithAR extends AggregateRoot {
    constructor(...args: any[]) {
      const maybeId = extractId(args[0]);
      super(maybeId ?? 'undefined-id', new Logger(Base.name));

      const baseInstance = new Base(...args);

      // Важно: не просто Object.assign, а копирование всех свойств + сохранение метаданных
      copyInstancePropsPreservingMetadata(baseInstance, this);
    }
  }

  // Возвращаем объединённый тип
  return WithAR as unknown as Constructor<InstanceType<TBase> & AggregateRoot>;
}
```

