## 👇 Хелперы

### Функция для извлечения `id` (универсально):

```ts
function extractId(arg: any): string | undefined {
  if (!arg) return;
  if (typeof arg === 'string') return arg;
  if (typeof arg === 'object' && 'id' in arg) return arg.id;
  if (typeof arg === 'object' && '_id' in arg) return arg._id;
}
```

### Функция копирования свойств с метаданными:

```ts
import 'reflect-metadata';

function copyInstancePropsPreservingMetadata(source: any, target: any) {
  const keys = Reflect.ownKeys(source);
  for (const key of keys) {
    const desc = Object.getOwnPropertyDescriptor(source, key);
    if (desc) {
      Object.defineProperty(target, key, desc);
    }

    // Копируем метаданные, если они есть (для class-transformer, class-validator, и т.п.)
    const metadataKeys = Reflect.getMetadataKeys(source, key);
    for (const metaKey of metadataKeys) {
      const meta = Reflect.getMetadata(metaKey, source, key);
      Reflect.defineMetadata(metaKey, meta, target, key);
    }
  }
}
```

